    "st_saved_browser": ["{p} · saved in browser", "{p} · guardado en el navegador", "{p} · 已保存在浏览器", "{p} · naka-save sa browser", "{p} · đã lưu trong trình duyệt", "{p} · enregistré dans le navigateur", "{p} · salvo no navegador", "{p} · حُفظ في المتصفح"],
    "st_saved_this_browser": ["{p} · saved in this browser", "{p} · guardado en este navegador", "{p} · 已保存在此浏览器", "{p} · naka-save sa browser na ito", "{p} · đã lưu trong trình duyệt này", "{p} · enregistré dans ce navigateur", "{p} · salvo neste navegador", "{p} · حُفظ في هذا المتصفح"],
    "st_storage_blocked": ["Browser blocked storage. Use Save ink into file.", "El navegador bloqueó el guardado. Usa Guardar tinta en el archivo.", "浏览器阻止了存储。请使用“把笔迹保存到文件”。", "Hinarangan ng browser ang pag-save. Gamitin ang I-save ang tinta sa file.", "Trình duyệt chặn lưu trữ. Hãy dùng Lưu nét mực vào tệp.", "Le navigateur bloque l'enregistrement. Utilisez Enregistrer l'encre dans le fichier.", "O navegador bloqueou o armazenamento. Use Salvar tinta no arquivo.", "منع المتصفح الحفظ. استخدم «حفظ الحبر في الملف»."],
    "st_no_ink_clear": ["{p} has no ink to clear", "{p} no tiene tinta que borrar", "{p} 没有可清除的笔迹", "Walang tintang mabubura sa {p}", "{p} không có nét mực để xóa", "{p} n'a pas d'encre à effacer", "{p} não tem tinta para limpar", "لا يوجد حبر لمسحه في {p}"],
    "st_all_cleared": ["All pages cleared in {p} · Undo brings it back", "Se borraron todas las páginas en {p} · Deshacer lo recupera", "{p} 的所有页面已清除 · 撤销可恢复", "Nabura ang lahat ng pahina sa {p} · Maibabalik ng Undo", "Đã xóa mọi trang ở {p} · Hoàn tác để lấy lại", "Toutes les pages effacées pour {p} · Annuler les fait revenir", "Todas as páginas limpas em {p} · Desfazer traz de volta", "مُسحت كل الصفحات في {p} · التراجع يعيدها"],
    "st_cleared": ["Cleared {p} · Undo brings it back", "{p} borrado · Deshacer lo recupera", "已清除 {p} · 撤销可恢复", "Nabura ang {p} · Maibabalik ng Undo", "Đã xóa {p} · Hoàn tác để lấy lại", "{p} effacé · Annuler le fait revenir", "{p} limpo · Desfazer traz de volta", "مُسح {p} · التراجع يعيده"],
    "st_page_no_ink": ["Page {n} has no ink in {p}", "La página {n} no tiene tinta en {p}", "第 {n} 页在 {p} 中没有笔迹", "Walang tinta ang pahina {n} sa {p}", "Trang {n} không có nét mực ở {p}", "La page {n} n'a pas d'encre pour {p}", "A página {n} não tem tinta em {p}", "الصفحة {n} ليس فيها حبر في {p}"],
    "st_page_cleared": ["Page {n} cleared · Undo brings it back", "Página {n} borrada · Deshacer la recupera", "第 {n} 页已清除 · 撤销可恢复", "Nabura ang pahina {n} · Maibabalik ng Undo", "Đã xóa trang {n} · Hoàn tác để lấy lại", "Page {n} effacée · Annuler la fait revenir", "Página {n} limpa · Desfazer traz de volta", "مُسحت الصفحة {n} · التراجع يعيدها"],
